<?php declare(strict_types=1);$e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$m=$module;$catalog=$m['catalog']??null;$release=$m['release']??null;$releaseNotes=is_array($release['release_notes']??null)?$release['release_notes']:['summary'=>(string)($release['release_notes']??''),'changes'=>[(string)($release['release_notes']??'')]];$history=is_array($catalog['history']??null)?$catalog['history']:[];$csrf=(string)($csrf_token??'');$classification=(string)($m['classification']??'v2');$isManagedV2=$classification==='v2'&&!empty($m['v2_installed']);$adoptionOperation=is_array($adoption_operation??null)?$adoption_operation:null;$adoptionRunning=is_array($adoptionOperation)&&($adoptionOperation['status']??'')==='running';$actionForm=static function(string $action,string $label,string $class='btn-primary',bool $disabled=false)use($m,$csrf,$e):string{return '<form method="post" action="/admin/module-catalog/action" class="catalog-action-form">'.\Modulon\Core\View::csrfField($csrf).'<input type="hidden" name="module_id" value="'.$e($m['id']).'"><input type="hidden" name="action" value="'.$e($action).'"><button class="btn '.$class.'" type="submit"'.($disabled?' disabled':'').'>'.$e($label).'</button></form>';};?>
