<div class="d-flex flex-wrap justify-content-between align-items-start gap-3 mt-3 mb-4"><div><div class="d-flex gap-2 align-items-center mb-2"><span class="badge <?= $classification==='v2'?'text-bg-primary':'text-bg-secondary' ?>"><?= $e($m['classification_label']??$m['origin_label']) ?></span><?php if($classification==='v2'&&($m['origin_label']??'Katalog')!=='Katalog'):?><span class="badge text-bg-secondary"><?= $e($m['origin_label']) ?></span><?php endif;?><?php if(!empty($m['retained'])&&!empty($m['has_owned_data'])):?><span class="badge text-bg-warning">Daten vorhanden</span><?php elseif(!empty($m['retained'])):?><span class="badge text-bg-secondary">Keine Moduldaten vorhanden</span><?php endif;?><?php if(!empty($m['is_beta'])):?><span class="badge rounded-pill text-bg-warning text-dark"><i class="bi bi-tools me-1"></i>Beta (In Entwicklung)</span><?php endif;?></div><h1 class="h3 mb-1"><?= $e($m['name']) ?></h1><p class="text-body-secondary mb-0"><?= $e($m['description']) ?></p></div><div class="catalog-actions"><?php if(!empty($m['update_available'])):?><div class="text-end"><strong class="d-block mb-2">Version <?= $e($m['available_version']) ?> verfügbar</strong><?= $actionForm('update','Aktualisieren') ?></div><?php elseif(!empty($m['adoptable'])):?><?= $actionForm('adopt',$adoptionRunning?'Adoption läuft…':'Auf Modul v2 umstellen','btn-primary',$adoptionRunning) ?><?php elseif(!empty($m['reinstallable'])&&!$adoptionRunning):?><a class="btn btn-primary" href="#reinstall-v2">Modul v2 neu installieren</a><?php elseif(empty($m['installed'])&&!$adoptionRunning):?><?= $actionForm('install',!empty($m['retained'])?'Neu installieren':'Installieren','btn-primary',empty($m['compatible'])) ?><?php elseif($isManagedV2):?><?= !empty($m['active'])?$actionForm('deactivate','Deaktivieren','btn-outline-secondary'):$actionForm('activate','Aktivieren') ?><?php endif;?></div></div>
