<div class="row g-4"><div class="col-12 col-lg-7"><section class="card app-card border-0 shadow-sm h-100"><div class="card-body p-4"><h2 class="h5 mb-3">Moduldetails</h2><dl class="row catalog-details"><dt class="col-sm-5">Technische ID</dt><dd class="col-sm-7"><code><?= $e($m['id']) ?></code></dd><dt class="col-sm-5">Aktueller Stand</dt><dd class="col-sm-7"><?php if($classification==='v1'):?>Modul v1 · an Core <?= $e($m['core_version']??'') ?> gebunden<?php else:?><?= $e($m['installed_version']!==null?'Modul v2 · Version '.$m['installed_version']:'Nicht installiert') ?><?php endif;?></dd><dt class="col-sm-5">Verfügbare Modul-v2-Version</dt><dd class="col-sm-7"><?= $e($m['available_version']??'—') ?></dd><dt class="col-sm-5">Datenstatus</dt><dd class="col-sm-7"><?php if(!empty($m['has_owned_data'])):?><?= !empty($m['retained'])?'Gespeicherte Moduldaten vorhanden':'Modul besitzt registrierte Daten' ?><?php elseif($classification==='v1'):?>Wird vor der Umstellung geprüft<?php else:?>Keine Moduldaten vorhanden<?php endif;?><?php if(!empty($m['data_schema_version'])):?> · Schema <?= (int)$m['data_schema_version'] ?><?php endif;?></dd><?php if($catalog):?><dt class="col-sm-5">Lizenz</dt><dd class="col-sm-7"><?= $e($catalog['license']) ?></dd><dt class="col-sm-5">Autor</dt><dd class="col-sm-7"><?= $e(implode(', ',$catalog['authors'])) ?></dd><dt class="col-sm-5">ModulNest</dt><dd class="col-sm-7"><?= $e($release['core']??'—') ?></dd><dt class="col-sm-5">PHP</dt><dd class="col-sm-7"><?= $e($release['php']??'—') ?></dd><dt class="col-sm-5">Links</dt><dd class="col-sm-7"><a href="<?= $e($catalog['homepage']) ?>">Homepage</a> · <a href="<?= $e($catalog['repository']) ?>">Repository</a></dd><?php endif;?></dl></div></section></div>
<div class="col-12 col-lg-5"><section class="card app-card border-0 shadow-sm h-100"><div class="card-body p-4"><h2 class="h5">Abhängigkeiten</h2><?php if(empty($release['dependencies'])):?><p class="text-body-secondary">Keine zusätzlichen Module erforderlich.</p><?php else:?><ul><?php foreach($release['dependencies'] as $id=>$range):?><li><code><?= $e($id) ?></code> <?= $e($range) ?></li><?php endforeach;?></ul><?php endif;?><?php if(!empty($m['last_operation'])):?><h2 class="h5 mt-4">Letzte Aktion</h2><p class="small mb-0"><?= $e($m['last_operation']['operation_type']) ?> · <?= $e($m['last_operation']['status']) ?> · <?= $e($m['last_operation']['created_at']) ?></p><?php endif;?></div></section></div></div>
<?php $portability=$m['data_portability']??[];if(!empty($portability['supported'])):?><section class="card app-card border-0 shadow-sm mt-4"><div class="card-body p-4"><h2 class="h5">Datenportabilität</h2><?php if(!empty($portability['available'])):?><p>Dieses aktive Modul stellt einen geprüften Export-/Import-Provider bereit.</p><div class="d-flex flex-wrap gap-2"><a class="btn btn-outline-primary" href="/admin/data-portability?module=<?= rawurlencode((string)$m['id']) ?>&amp;mode=export">Daten exportieren</a><a class="btn btn-outline-primary" href="/admin/data-portability?module=<?= rawurlencode((string)$m['id']) ?>&amp;mode=import">Daten importieren</a></div><?php elseif(empty($portability['central_active'])):?><p class="mb-2">Der Modul-Provider ist vorhanden, aber die zentrale Funktion „Export / Import“ ist nicht aktiv.</p><a href="/admin/modules">Zentrale Funktion aktivieren</a><?php else:?><p class="mb-0 text-body-secondary">Der Provider ist erst verfügbar, wenn das Modul aktiv ist.</p><?php endif;?></div></section><?php endif;?>
<?php if(!empty($m['update_available'])):?><section class="card app-card border-primary shadow-sm mt-4"><div class="card-body p-4"><h2 class="h5">Neu in Version <?= $e($m['available_version']) ?></h2><p class="fs-5 mb-3"><?= $e($m['name']) ?> <strong><?= $e($m['installed_version']) ?> → <?= $e($m['available_version']) ?></strong></p><ul><?php foreach(($releaseNotes['changes']??[]) as $change):?><li><?= $e($change) ?></li><?php endforeach;?></ul><hr><h3 class="h6">Aktualisierungsplan</h3><ul class="mb-0"><li>Datenbankmigrationen: <?= (int)($release['migration_count']??0) ?></li><li>Backup: wird erstellt und geprüft</li><li>Abhängigkeiten: <?= empty($release['dependencies'])?'keine Änderungen':'werden vorab geprüft' ?></li></ul></div></section><?php endif;?>
<?php if($history!==[]):?><section class="card app-card border-0 shadow-sm mt-4" data-version-history><div class="card-body p-4"><h2 class="h5">Versionsverlauf</h2><?php foreach($history as $position=>$entry):?><?php if($position===0):?><div class="mb-3"><h3 class="h6 mb-1">Version <?= $e($entry['version']) ?> <small class="text-body-secondary"><?= $e($entry['date']) ?></small></h3><ul class="mb-0"><?php foreach($entry['changes'] as $change):?><li><?= $e($change) ?></li><?php endforeach;?></ul></div><?php else:?><details class="border-top pt-2 mt-2"><summary>Version <?= $e($entry['version']) ?> · <?= $e($entry['date']) ?></summary><ul class="mt-2 mb-0"><?php foreach($entry['changes'] as $change):?><li><?= $e($change) ?></li><?php endforeach;?></ul></details><?php endif;?><?php endforeach;?></div></section><?php endif;?>
<?php if($isManagedV2):?><section class="card app-card border-0 shadow-sm mt-4"><div class="card-body p-4"><h2 class="h5">Modul deinstallieren</h2><?php if(!empty($m['has_owned_data'])):?><p>Der Modulcode wird entfernt. <strong>Die Moduldaten bleiben standardmäßig erhalten</strong> und können bei einer späteren Neuinstallation weiterverwendet werden.</p><?= $actionForm('uninstall','Modul entfernen, Daten behalten','btn-outline-danger') ?><?php else:?><p>Der Modulcode wird entfernt. Dieses Modul besitzt keine eigenen persistenten Daten; Core-Daten bleiben unberührt.</p><?= $actionForm('uninstall','Modul entfernen','btn-outline-danger') ?><?php endif;?></div></section><?php endif;?>
<?php if(!empty($m['retained'])):?><section class="card border-danger shadow-sm mt-4"><div class="card-body p-4"><h2 class="h5 text-danger">Daten endgültig löschen</h2><p>Diese Aktion ist irreversibel. Tabellen, Einstellungen und Modulstorage aus dem registrierten Ownership-Plan werden gelöscht. Das Audit bleibt erhalten.</p><?php if(!empty($m['resources'])):?><details class="mb-3"><summary>Betroffene Datenarten anzeigen</summary><ul class="small mt-2"><?php foreach($m['resources'] as $resource):?><li><?= $e($resource['resource_type']) ?>: <code><?= $e($resource['resource_key']) ?></code></li><?php endforeach;?></ul></details><?php endif;?><form method="post" action="/admin/module-catalog/action" class="catalog-action-form"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="module_id" value="<?= $e($m['id']) ?>"><input type="hidden" name="action" value="purge"><label class="form-label" for="confirm_module_id">Zur Bestätigung technische ID eingeben: <code><?= $e($m['id']) ?></code></label><input class="form-control mb-3" id="confirm_module_id" name="confirm_module_id" required autocomplete="off"><button class="btn btn-danger" type="submit">Daten endgültig löschen</button></form></div></section><?php endif;?>
<script>document.querySelectorAll('.catalog-action-form').forEach(form=>form.addEventListener('submit',()=>form.querySelectorAll('button').forEach(button=>{button.disabled=true;button.setAttribute('aria-busy','true');})));(()=>{const panel=document.querySelector('[data-adoption-operation]');if(!panel)return;const moduleId=panel.dataset.moduleId;const title=panel.querySelector('[data-operation-title]');const message=panel.querySelector('[data-operation-message]');const detail=panel.querySelector('[data-operation-detail]');const bar=panel.querySelector('[data-operation-progress]');const render=operation=>{if(!operation)return;const status=operation.status||'running';title.textContent=status==='failed'?'Adoption fehlgeschlagen':status==='succeeded'?'Adoption abgeschlossen':'Adoption läuft im Hintergrund';message.textContent=operation.message||'Status wird ermittelt.';const total=Number(operation.total_bytes||0),done=Number(operation.completed_bytes||0),percent=total>0?Math.min(100,Math.round(done/total*100)):0;bar.style.width=percent+'%';detail.textContent='Phase: '+(operation.phase||'—')+(total>0?' · '+percent+' %':'');panel.className='alert '+(status==='failed'?'alert-danger':status==='succeeded'?'alert-success':'alert-info');if(status==='running')setTimeout(poll,1500);else if(status==='succeeded')setTimeout(()=>location.reload(),1200);};const poll=()=>fetch('/admin/module-catalog-operation/status?module_id='+encodeURIComponent(moduleId),{headers:{Accept:'application/json'},cache:'no-store'}).then(response=>response.ok?response.json():Promise.reject()).then(data=>render(data.operation)).catch(()=>setTimeout(poll,3000));<?php if($adoptionRunning):?>poll();<?php endif;?>})();</script>
